(()=>{const d=document;const menuBtn=d.querySelector('[data-menu-btn]');const nav=d.querySelector('[data-nav]');if(menuBtn&&nav){menuBtn.addEventListener('click',()=>{const open=nav.getAttribute('data-open')==='true';nav.setAttribute('data-open',String(!open));menuBtn.setAttribute('aria-expanded',String(!open));});d.addEventListener('click',e=>{if(!nav.contains(e.target)&&!menuBtn.contains(e.target)&&window.innerWidth<760){nav.setAttribute('data-open','false');menuBtn.setAttribute('aria-expanded','false');}});}const banner=d.querySelector('[data-cookie-banner]');const consentKey='cookie-consent-v2';if(banner){const saved=localStorage.getItem(consentKey);if(!saved){banner.setAttribute('data-visible','true');}banner.querySelectorAll('[data-cookie-choice]').forEach(btn=>btn.addEventListener('click',()=>{localStorage.setItem(consentKey,btn.getAttribute('data-cookie-choice'));banner.setAttribute('data-visible','false');}));}const labels={name:'الاسم',phone:'رقم الجوال',email:'البريد الإلكتروني',vehicle:'نوع المركبة',coverage:'نوع التغطية',city:'المدينة',preferred:'وسيلة التواصل المفضلة',message:'تفاصيل إضافية',subject:'موضوع الرسالة'};d.querySelectorAll('[data-mailto-form]').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();if(typeof form.reportValidity==='function'&&!form.reportValidity())return;const fd=new FormData(form);const subject=fd.get('subject')||fd.get('coverage')||'طلب تواصل من خدمات الرقمية ذكية';const body=[];for(const [key,val] of fd.entries()){if(!val||key==='subject')continue;body.push(`${labels[key]||key}: ${String(val).trim()}`);}body.push('');body.push(`الصفحة: ${window.location.href}`);const mail=`mailto:info@zmduqlwu.elementor.cloud?subject=${encodeURIComponent(String(subject))}&body=${encodeURIComponent(body.join('\n'))}`;window.location.href=mail;try{form.reset();}catch(e){}const status=form.querySelector('[data-form-status]');if(status){status.textContent='تم تجهيز رسالة البريد الإلكتروني. إن لم يفتح التطبيق لديك، استخدم البريد المباشر: info@zmduqlwu.elementor.cloud';}});});d.querySelectorAll('[data-current-year]').forEach(el=>{el.textContent=String(new Date().getFullYear());});})();